(function() {
    'use strict';

    class CostLabAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'CostLab: Management Accounting & Margin Decisions';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    titleDefault: 'Round 1: ABC Model Redesign',
                    descHtml: '<p>Andina Consumer Products allocates <strong>$6.7M</strong> of manufacturing overhead using a single driver: <strong>direct labor hours</strong>. The CFO suspects this distorts product profitability.</p><table class="costlab-sim-data-table"><tr><th>Activity Pool</th><th>Annual Cost</th><th>Current Driver</th></tr><tr><td>Machine Setups</td><td>$1.8M</td><td>Direct Labor Hours</td></tr><tr><td>Quality Inspections</td><td>$2.1M</td><td>Direct Labor Hours</td></tr><tr><td>Raw Material Procurement</td><td>$0.9M</td><td>Direct Labor Hours</td></tr><tr><td>Inbound Logistics</td><td>$0.7M</td><td>Direct Labor Hours</td></tr><tr><td>Customer Service</td><td>$1.2M</td><td>Direct Labor Hours</td></tr></table><p>For each activity pool, select the cost driver that best reflects the <strong>true cause</strong> of cost variation.</p>'
                },
                {
                    titleKey: 'round2_title',
                    titleDefault: 'Round 2: Variance Analysis',
                    descHtml: '<p>Review four key variances from the <strong>Q3 Variance Report</strong>. For each, determine the correct interpretation.</p><p>Be careful: not every adverse variance indicates poor performance, and not every favorable variance is good news. Distinguish signal from noise.</p>'
                },
                {
                    titleKey: 'round3_title',
                    titleDefault: 'Round 3: Zero-Based Budget',
                    descHtml: '<p>Current overhead: <strong>$6.7M</strong>. Using zero-based methodology, rebuild the budget from zero.</p><p><strong>Outsourcing offer:</strong> A third party will provide setup and inspection services for <strong>$1.9M</strong> (vs. $2.6M internal). However:</p><table class="costlab-sim-data-table"><tr><th>Factor</th><th>Detail</th></tr><tr><td>Quality Standards</td><td>Not independently validated</td></tr><tr><td>Workforce Impact</td><td>8 technician roles eliminated ($320K severance)</td></tr><tr><td>Response Time</td><td>48 hours (vs. 4 hours internal)</td></tr></table><p>Set your target overhead budget and choose your capacity strategy.</p>'
                },
                {
                    titleKey: 'round4_title',
                    titleDefault: 'Round 4: Product Portfolio Decision',
                    descHtml: '<p>Armed with ABC profitability data, make strategic decisions for each product line.</p><table class="costlab-sim-data-table"><tr><th>Product Line</th><th>Revenue</th><th>Absorption EBIT</th><th>ABC EBIT</th><th>Contribution Margin</th></tr><tr><td>A — Personal Care</td><td>$18.9M (45%)</td><td>12.3%</td><td>4.1%</td><td>$5.1M</td></tr><tr><td>B — Household Cleaning</td><td>$16.0M (38%)</td><td>6.8%</td><td>11.4%</td><td>$4.8M</td></tr><tr><td>C — Food Ingredients</td><td>$7.1M (17%)</td><td>(3.2%)</td><td>3.8%</td><td>$2.4M</td></tr></table><p><strong>Key data for Line C:</strong> Contribution margin is <strong>$2.4M positive</strong>. Only <strong>$0.6M</strong> of fixed costs are truly avoidable if discontinued. The remaining $1.8M reallocates to Lines A and B.</p>'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    scoreHistory: [],
                    roundDetails: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = round.titleDefault;

            var descEl = document.getElementById('roundDescription');
            if (descEl) descEl.innerHTML = round.descHtml;

            var panel = document.getElementById('decisionPanel');
            if (!panel) return;

            var html = '';

            if (idx === 0) {
                html += '<h4 data-i18n="r1_heading">Select Cost Drivers for Each Activity</h4>';
                var activities = [
                    { id: 'driver0', label: 'Machine Setups ($1.8M)', opts: ['Direct Labor Hours', 'Number of Setups', 'Machine Hours'] },
                    { id: 'driver1', label: 'Quality Inspections ($2.1M)', opts: ['Direct Labor Hours', 'Number of Inspections', 'Units Produced'] },
                    { id: 'driver2', label: 'Raw Material Procurement ($0.9M)', opts: ['Direct Labor Hours', 'Number of Purchase Orders', 'Units Produced'] },
                    { id: 'driver3', label: 'Inbound Logistics ($0.7M)', opts: ['Direct Labor Hours', 'Number of Receiving Events', 'Weight Received'] },
                    { id: 'driver4', label: 'Customer Service ($1.2M)', opts: ['Direct Labor Hours', 'Number of Customer Orders', 'Revenue'] }
                ];
                for (var i = 0; i < activities.length; i++) {
                    var a = activities[i];
                    html += '<label for="' + a.id + '">' + a.label + '</label>';
                    html += '<select id="' + a.id + '">';
                    for (var j = 0; j < a.opts.length; j++) {
                        html += '<option value="' + j + '">' + a.opts[j] + '</option>';
                    }
                    html += '</select>';
                }
            } else if (idx === 1) {
                html += '<h4 data-i18n="r2_heading">Classify Each Variance</h4>';
                var variances = [
                    {
                        id: 'var0',
                        label: 'Line A Material Price Variance: $285K Adverse',
                        detail: 'Palm oil costs rose 18% in Q3. Procurement secured contracts 4% below spot price.',
                        opts: ['Actionable — Procurement Failure', 'Non-Actionable — Market Movement', 'Actionable — Supplier Issue']
                    },
                    {
                        id: 'var1',
                        label: 'Line B Labor Efficiency Variance: $92K Favorable',
                        detail: 'Production completed ahead of schedule. Factory manager notes setup equipment issues during the period.',
                        opts: ['Positive — Labor Efficiency Gain', 'Risk Indicator — Quality Checks Skipped', 'Positive — Process Improvement']
                    },
                    {
                        id: 'var2',
                        label: 'Line C Fixed Overhead Volume Variance: $178K Adverse',
                        detail: 'Production volume fell 12% below budget. Two customer orders deferred to Q4.',
                        opts: ['Production Inefficiency', 'Commercial Issue — Volume Shortfall', 'Overhead Cost Overrun']
                    },
                    {
                        id: 'var3',
                        label: 'Line A Standard Cost Update Variance: $47K',
                        detail: 'Material standards updated July 1 mid-quarter. Variance spans pre- and post-update periods.',
                        opts: ['Investigate Full Amount', 'Split Pre/Post Standard Change', 'Ignore — Immaterial']
                    }
                ];
                for (var i = 0; i < variances.length; i++) {
                    var v = variances[i];
                    html += '<label for="' + v.id + '">' + v.label + '</label>';
                    html += '<div class="costlab-sim-detail">' + v.detail + '</div>';
                    html += '<select id="' + v.id + '">';
                    for (var j = 0; j < v.opts.length; j++) {
                        html += '<option value="' + j + '">' + v.opts[j] + '</option>';
                    }
                    html += '</select>';
                }
            } else if (idx === 2) {
                html += '<h4 data-i18n="r3_heading">Zero-Based Budget Decisions</h4>';
                html += '<label for="budgetInput" data-i18n="budget_label">Target Overhead Budget ($M)</label>';
                html += '<input type="number" id="budgetInput" min="3.0" max="8.0" step="0.1" value="6.0">';
                html += '<div class="costlab-sim-detail">Current overhead: $6.7M. Propose a ZBB target between $3.0M and $8.0M.</div>';
                html += '<label for="outsourceSelect" data-i18n="outsource_label">Setup and Inspection Capacity Strategy</label>';
                html += '<select id="outsourceSelect">';
                html += '<option value="0">Keep Internal (current cost: $2.6M)</option>';
                html += '<option value="1">Full Outsource ($1.9M + $320K severance)</option>';
                html += '<option value="2">Hybrid Model (outsource Line B setup/inspection, keep Line A internal)</option>';
                html += '</select>';
            } else if (idx === 3) {
                html += '<h4 data-i18n="r4_heading">Product Line Decisions</h4>';
                var lines = [
                    { id: 'lineA', label: 'Line A — Personal Care (ABC EBIT 4.1%, was 12.3% under absorption)', opts: ['Grow', 'Maintain', 'Re-price Upward', 'Discontinue'] },
                    { id: 'lineB', label: 'Line B — Household Cleaning (ABC EBIT 11.4%, was 6.8% under absorption)', opts: ['Grow', 'Maintain', 'Re-price', 'Discontinue'] },
                    { id: 'lineC', label: 'Line C — Food Ingredients (ABC EBIT 3.8%, was -3.2% under absorption)', opts: ['Grow', 'Maintain', 'Re-price Upward', 'Discontinue'] }
                ];
                for (var i = 0; i < lines.length; i++) {
                    var l = lines[i];
                    html += '<label for="' + l.id + '">' + l.label + '</label>';
                    html += '<select id="' + l.id + '">';
                    for (var j = 0; j < l.opts.length; j++) {
                        html += '<option value="' + j + '">' + l.opts[j] + '</option>';
                    }
                    html += '</select>';
                }
                html += '<div class="costlab-sim-detail">Remember: Line C has $2.4M positive contribution margin. Only $0.6M of fixed costs are truly avoidable if discontinued.</div>';
            }

            panel.innerHTML = html;
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;
            this._updateBriefing(window.mySimulation.state);

            if (period === 1) {
                for (var i = 0; i < 5; i++) {
                    var sel = document.getElementById('driver' + i);
                    if (sel) decisions['driver' + i] = parseInt(sel.value);
                }
            } else if (period === 2) {
                for (var i = 0; i < 4; i++) {
                    var sel = document.getElementById('var' + i);
                    if (sel) decisions['var' + i] = parseInt(sel.value);
                }
            } else if (period === 3) {
                var budgetEl = document.getElementById('budgetInput');
                if (budgetEl) decisions.budget = parseFloat(budgetEl.value);
                var outsourceEl = document.getElementById('outsourceSelect');
                if (outsourceEl) decisions.outsource = parseInt(outsourceEl.value);

                if (!decisions.budget || decisions.budget < 3.0 || decisions.budget > 8.0) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('budget_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 4) {
                var lineAEl = document.getElementById('lineA');
                if (lineAEl) decisions.lineA = parseInt(lineAEl.value);
                var lineBEl = document.getElementById('lineB');
                if (lineBEl) decisions.lineB = parseInt(lineBEl.value);
                var lineCEl = document.getElementById('lineC');
                if (lineCEl) decisions.lineC = parseInt(lineCEl.value);
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var period = state.currentPeriod;
            var score = 0;
            var maxScore = 0;
            var feedback = '';
            var roundName = '';

            if (period === 1) {
                roundName = 'ABC Redesign';
                maxScore = 25;
                var correct = [1, 1, 1, 1, 1];
                var partialIdx = [null, null, null, 2, 2];
                for (var i = 0; i < 5; i++) {
                    var chosen = d['driver' + i];
                    if (chosen === correct[i]) {
                        score += 5;
                    } else if (partialIdx[i] !== null && chosen === partialIdx[i]) {
                        score += 3;
                    }
                }
                if (score >= 23) {
                    feedback = 'Excellent ABC model! You correctly identified causal drivers for overhead activities. The revised profitability picture inverts: Line A drops to 4.1% EBIT while Line C rises to 3.8%.';
                } else if (score >= 15) {
                    feedback = 'Good progress. Some driver selections could be improved. Remember: batch-level costs are driven by the number of batches, not by production volume.';
                } else {
                    feedback = 'Review ABC principles: match each activity to the driver that causes cost variation, not volume-based proxies like direct labor hours.';
                }
            } else if (period === 2) {
                roundName = 'Variance Analysis';
                maxScore = 25;
                var correct = [1, 1, 1, 1];
                for (var i = 0; i < 4; i++) {
                    if (d['var' + i] === correct[i]) {
                        score += 6;
                    }
                }
                if (score === 24) score = 25;
                if (score >= 20) {
                    feedback = 'Strong variance analysis! You correctly distinguished signal from noise: the palm oil MPV reflects market forces, the favorable LEV hides a quality risk, and the FOVV is a commercial issue.';
                } else if (score >= 12) {
                    feedback = 'Partial credit. Remember: adverse variances are not always problems, and favorable variances are not always good news. Check root causes before assigning blame.';
                } else {
                    feedback = 'Review variance interpretation. The sign (favorable vs. adverse) tells you the direction, not whether the underlying cause is good or bad.';
                }
            } else if (period === 3) {
                roundName = 'Zero-Based Budget';
                maxScore = 20;
                var budget = d.budget || 6.7;
                if (budget >= 5.0 && budget <= 6.0) {
                    score += 10;
                } else if (budget >= 4.5 && budget <= 6.5) {
                    score += 7;
                } else if (budget >= 4.0 && budget <= 7.0) {
                    score += 4;
                } else {
                    score += 2;
                }
                if (d.outsource === 2) {
                    score += 10;
                } else if (d.outsource === 0) {
                    score += 6;
                } else {
                    score += 3;
                }
                if (score >= 18) {
                    feedback = 'Excellent budget discipline! The hybrid outsourcing model balances cost savings with operational flexibility and quality control where it matters most.';
                } else if (score >= 12) {
                    feedback = 'Reasonable budget. Consider all dimensions of the outsourcing decision: headline savings, severance, quality risk, and scheduling flexibility.';
                } else {
                    feedback = 'ZBB requires challenging every cost from zero. Full outsourcing may appear cheaper but carries hidden costs in quality risk and lost flexibility.';
                }
            } else if (period === 4) {
                roundName = 'Portfolio Decision';
                maxScore = 30;
                var lineAScores = [-5, 3, 10, -5];
                var lineBScores = [10, 5, 3, -10];
                var lineCScores = [5, 8, 10, -15];

                var rawScore = 0;
                rawScore += lineAScores[d.lineA || 0];
                rawScore += lineBScores[d.lineB || 0];
                rawScore += lineCScores[d.lineC || 0];
                score = Math.max(0, rawScore);

                if (d.lineC === 3) {
                    feedback = 'Critical error: Discontinuing Line C destroys $1.8M of value! Line C contributes $2.4M to fixed costs, but only $0.6M is truly avoidable. The remaining $1.8M reallocates to Lines A and B, worsening total EBIT.';
                } else if (score >= 25) {
                    feedback = 'Outstanding portfolio strategy! You correctly used ABC data to re-price the mispriced lines and grow the most efficient product. The fixed cost trap was avoided.';
                } else if (score >= 15) {
                    feedback = 'Good decisions overall. Ensure Line A is re-priced to reflect its true overhead burden, and Line B is prioritized for growth given its strong ABC margins.';
                } else {
                    feedback = 'Review ABC profitability signals. Line A needs re-pricing (high overhead consumer), Line B is the growth candidate (most efficient), and Line C is actually profitable under ABC.';
                }
            }

            state.domainState.totalScore += score;
            state.domainState.scoreHistory.push(score);
            state.domainState.roundDetails.push({
                round: period,
                roundName: roundName,
                score: score,
                maxScore: maxScore,
                feedback: feedback
            });

            // v1.1.0: expose a normalized 0-100 overall in the shape the reporting layer reads
            // (score / performance.overallScore), using the sim's own percentage definition.
            var _maxSoFar = 0;
            for (var _k = 0; _k < state.domainState.roundDetails.length; _k++) { _maxSoFar += state.domainState.roundDetails[_k].maxScore || 0; }
            var _pct = _maxSoFar > 0 ? Math.round(state.domainState.totalScore / _maxSoFar * 100) : 0;
            var _overall = Math.max(0, Math.min(100, _pct));
            var _rating = 'Needs Review';
            if (_overall >= 85) _rating = 'Excellent'; else if (_overall >= 65) _rating = 'Competent'; else if (_overall >= 45) _rating = 'Developing';
            state.domainState.score = _overall;
            state.domainState.performance = { overallScore: _overall, rating: _rating, rawScore: state.domainState.totalScore };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: period,
                roundName: roundName,
                score: score,
                maxScore: maxScore,
                totalScore: state.domainState.totalScore,
                feedback: feedback
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('totalScoreDisplay', 'domainState.totalScore',
                function(v) { return v + ' pts'; });
            uiManager.bind('roundScoreDisplay', 'results.score',
                function(v) {
                    var mx = window.mySimulation.state.results ? window.mySimulation.state.results.maxScore : 0;
                    return v + '/' + mx;
                });
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Round Score',
                            data: [],
                            backgroundColor: [
                                'rgba(44,95,138,0.7)',
                                'rgba(39,174,96,0.7)',
                                'rgba(243,156,18,0.7)',
                                'rgba(155,89,182,0.7)'
                            ],
                            borderColor: [
                                '#2c5f8a',
                                '#27ae60',
                                '#f39c12',
                                '#9b59b6'
                            ],
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Score by Round' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 30 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var roundLabels = ['ABC Redesign', 'Variance Analysis', 'Zero-Based Budget', 'Portfolio Decision'];
            var data = state.domainState.scoreHistory;
            return {
                scoreChart: {
                    labels: roundLabels.slice(0, data.length),
                    datasets: [{ data: data }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = 0;
            var maxPossible = 0;
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results;
                if (r) {
                    totalScore += r.score || 0;
                    maxPossible += r.maxScore || 0;
                }
            }
            var pct = maxPossible > 0 ? (totalScore / maxPossible * 100) : 0;

            var performance = 'Needs Review';
            if (pct >= 85) performance = 'Excellent';
            else if (pct >= 65) performance = 'Competent';
            else if (pct >= 45) performance = 'Developing';

            var insights = [];

            if (history.length >= 4 && history[3].decisions && history[3].decisions.lineC === 3) {
                insights.push('Key learning: Discontinuing Line C destroys $1.8M of value. Its positive contribution margin exceeds avoidable fixed costs. Fixed overhead does not disappear — it reallocates.');
            }

            if (pct >= 85) {
                insights.push('Excellent grasp of management accounting: ABC costing, variance interpretation, zero-based budgeting, and contribution-based portfolio decisions.');
            } else if (pct >= 65) {
                insights.push('Solid understanding of cost analysis. Review the connection between cost allocation methods and strategic decision quality.');
            } else {
                insights.push('Focus on the core principle: management accounting exists to support decisions, not to report history. The overhead allocation method determines which products appear profitable.');
            }

            var overallScore = Math.max(0, Math.min(100, Math.round(pct)));
            return {
                totalScore: totalScore,
                maxPossible: maxPossible,
                percentage: Math.round(pct),
                overallScore: overallScore,
                score: overallScore,
                performance: performance,
                insights: insights
            };
